describe('Dropdown Menu Keyboard Navigation', () => {
  beforeEach(() => {
    cy.visit('/dropdown-menu');
  });

  it('should navigate dropdown menu items using arrow keys', () => {
    // Open the dropdown menu
    cy.get('[data-testid="dropdown-button"]').click();

    // Verify dropdown is visible
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // Navigate to first item using down arrow
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}');
    cy.get('[data-testid="dropdown-item-1"]').should('have.class', 'active');

    // Navigate to second item using down arrow
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}');
    cy.get('[data-testid="dropdown-item-2"]').should('have.class', 'active');

    // Navigate to third item using down arrow
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}');
    cy.get('[data-testid="dropdown-item-3"]').should('have.class', 'active');

    // Navigate to first item using up arrow
    cy.get('[data-testid="dropdown-menu"]').type('{uparrow}');
    cy.get('[data-testid="dropdown-item-2"]').should('have.class', 'active');

    // Navigate to first item using up arrow
    cy.get('[data-testid="dropdown-menu"]').type('{uparrow}');
    cy.get('[data-testid="dropdown-item-1"]').should('have.class', 'active');

    // Press Enter to select the active item
    cy.get('[data-testid="dropdown-menu"]').type('{enter}');
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');
    cy.get('[data-testid="dropdown-button"]').should('be.visible');
  });

  it('should handle keyboard navigation with edge cases', () => {
    // Open the dropdown menu
    cy.get('[data-testid="dropdown-button"]').click();

    // Navigate to last item using down arrow
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}{downarrow}{downarrow}');
    cy.get('[data-testid="dropdown-item-3"]').should('have.class', 'active');

    // Navigate past last item (should wrap to first)
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}');
    cy.get('[data-testid="dropdown-item-1"]').should('have.class', 'active');

    // Navigate to first item using up arrow
    cy.get('[data-testid="dropdown-menu"]').type('{uparrow}');
    cy.get('[data-testid="dropdown-item-3"]').should('have.class', 'active');

    // Navigate past first item (should wrap to last)
    cy.get('[data-testid="dropdown-menu"]').type('{uparrow}');
    cy.get('[data-testid="dropdown-item-3"]').should('have.class', 'active');

    // Press Escape to close dropdown
    cy.get('[data-testid="dropdown-menu"]').type('{escape}');
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');

    // Verify dropdown button is still visible
    cy.get('[data-testid="dropdown-button"]').should('be.visible');
  });
});
